/**
 * Ruprizzle Studio Embedded Hypermedia Engine (HTMX 2.x compatible subset)
 * Pure client-side zero-dependency script for declarative AJAX HTML swaps.
 */
(function() {
  function initHtmx(root) {
    const elements = (root || document).querySelectorAll('[hx-get], [hx-post], [hx-patch], [hx-delete]');
    elements.forEach(el => {
      if (el._htmxBound) return;
      el._htmxBound = true;

      const trigger = el.getAttribute('hx-trigger') || (el.tagName === 'FORM' ? 'submit' : 'click');
      const targetSelector = el.getAttribute('hx-target');
      const swapMethod = el.getAttribute('hx-swap') || 'innerHTML';

      el.addEventListener(trigger, async function(e) {
        if (el.tagName === 'FORM' || el.tagName === 'A' || el.getAttribute('type') === 'submit') {
          e.preventDefault();
        }

        const method = el.hasAttribute('hx-get') ? 'GET' :
                       el.hasAttribute('hx-post') ? 'POST' :
                       el.hasAttribute('hx-patch') ? 'PATCH' : 'DELETE';
        const url = el.getAttribute('hx-get') || el.getAttribute('hx-post') ||
                    el.getAttribute('hx-patch') || el.getAttribute('hx-delete');

        let body = null;
        let headers = { 'HX-Request': 'true' };

        if (el.tagName === 'FORM') {
          const formData = new FormData(el);
          body = new URLSearchParams(formData);
          headers['Content-Type'] = 'application/x-www-form-urlencoded';
        } else if (el.hasAttribute('hx-vals')) {
          try {
            const vals = JSON.parse(el.getAttribute('hx-vals'));
            body = new URLSearchParams(vals);
            headers['Content-Type'] = 'application/x-www-form-urlencoded';
          } catch(err) {}
        }

        try {
          const res = await fetch(url, {
            method: method,
            headers: headers,
            body: method !== 'GET' ? body : undefined
          });

          if (!res.ok) {
            const errText = await res.text();
            console.error('HTMX error:', res.status, errText);
            alert('Operation failed: ' + errText);
            return;
          }

          const html = await res.text();
          let target = document.querySelector(targetSelector);
          if (!target) target = el;

          if (swapMethod === 'outerHTML') {
            target.outerHTML = html;
          } else if (swapMethod === 'beforeend') {
            target.insertAdjacentHTML('beforeend', html);
          } else {
            target.innerHTML = html;
          }

          initHtmx(target);
          if (window.Alpine && window.Alpine.initTree) {
            window.Alpine.initTree(target);
          }
        } catch (err) {
          console.error('HTMX request failed:', err);
        }
      });
    });
  }

  document.addEventListener('DOMContentLoaded', () => initHtmx(document));
  window.htmx = { process: initHtmx };
})();
